// Convert input polygons to CGAL format
    Polygon_2 poly1, poly2;
    for (const auto& p : P1.vectorPoints()) {
        poly1.push_back(Point_2(p.x(), p.y()));
    }
    for (const auto& p : P2.vectorPoints()) {
        poly2.push_back(Point_2(p.x(), p.y()));
    }

    // Compute the difference
    Pwh_list_2 result;
    CGAL::difference(poly1, poly2, std::back_inserter(result));

    // Convert result to vector
    std::vector<PolygonWithHoles2d> output;
    for (const auto& pwh : result) {
        output.push_back(pwh);
    }
    return output;

